function createStack() {
  const items = [];

  return {
    push: (item) => items.push(item),
    pop: () => items.pop(),
  };
}

const a = createStack();
const b = createStack();

a.push("x");
console.log(a.push("y"));
console.log(b.push("z"));
console.log(a.pop());
console.log(b.pop());
console.log(typeof b.pop());
